messageHandlers.script:
	try:
		provider = self.view.custom.provider.strip('[]')
	except:
		return
	UDTPath = self.view.custom.selectedUDTType
	firstInstance = self.view.custom.firstInstance
	writeTags = self.view.custom.writeTags
	try:
		splitPath = UDTPath.split("]",1)[1]
	except:
		splitPath = UDTPath
	if splitPath == None:
		return
#	self.view.custom.test = splitPath
	#self.getChild('FlexContainer').getChild('FlexContainer_0').getChild('Label').props.text = splitPath
#	self.getChild('debug').props.params.text = splitPath

	BACnetExclude = [
	"/System/Write_Trigger",
	"/System/Object_Name",
	"/System/Relinquish_Default",
	"/System/OR_Val",
	"/System/Op_OR",
	"/System/Release_OR",
	"/System/OOS_Val",
	"/System/DenyTrigger",
	"/System/Priority_Array",
	"/System/Read_Trigger",
	"/System/OOS_Cmd",
	"/System/Object_Id",
	"/Status/OR_Sts",
	"/Status/Flt",
	"/Status/OOS",
	"/Alarms/In_Alm"
	]

	query = {
	  "options": {
	    "includeUdtMembers": True,
	    "includeUdtDefinitions": False
	  },
	  "condition": {
	    "hierarchy": {
	      "typeId": UDTPath,
	      "relationship": "SubType"
	    },
	    "attributes": {
	      "values": [],
	      "requireAll": True
	    },
	    "properties": {
	      "op": "Or",
	      "conditions": [
	        {
	          "op": "And",
	          "conditions": [
	            {
	              "prop": "tagType",
	              "comp": "Like",
	              "value": "AtomicTag"
	            }
	          ]
	        }
	      ]
	    }
	  },
	  "returnProperties": [
	    "formatString",
	    "tagType",
	    "engUnit",
	    "dataType"
	  ]
	}

	results = system.tag.query(provider, query)
	self.view.custom.test = firstInstance

	replaceDict = {
	    "Volts_": ["V","#,##0"],
	    "Cur_": ["A","#,##0.0"],
	    "Freq": ["Hz","#,##0"],
	    "kVA": ["kVA","#,##0.00"],
	    "kW": ["kW","#,##0.00"],
#	    "Ttl_Load": ["kW","#,##0.00"],
	    "Temp_F": ["\xb0F","#,##0.0"],
	    "Temp_C": ["\xb0C","#,##0.0"]
    }

	tagList = []
	for result in results:
		if str(firstInstance) not in str(result['fullPath']):
			continue
		oList = {}
		valueUnit = ""
		valueFormat = ""

		tagPart = '{...}'+str(result['fullPath']).replace(firstInstance,"")
		if '/Config' in tagPart:
			continue
#		BACnetTest = tagPart.rsplit("/",2)
#		BACnetPart = "/"+BACnetTest[1]+"/"+BACnetTest[2]
#		if BACnetPart in BACnetExclude:
#			continue
#		elif tagPart == '{...}':
#			continue
		oList["newEngUnit"] = ""
		oList["newFormatString"] = ""

		for key, value in replaceDict.items():
			valueUnit = value[0]
			valueFormat = value[1]
			if str(key).lower() in tagPart.lower():
				try:
					BACnetSplit = str(eachTag).split(str(key))[-1]
				except:
				    BACnetSplit = ""
				if "System" in BACnetSplit and "Present_Val" not in BACnetSplit:
					continue
				else:
					if str(key).lower()+"r" in tagPart.lower():
					    valueUnit = valueUnit+"R"
					    key = key+"R"
					if str(key).lower()+"h" in tagPart.lower():
					    valueUnit = valueUnit+"h"

					if valueUnit <> result['engUnit']:
						oList["newEngUnit"] = valueUnit
					if valueFormat <> result['formatString']:
						oList["newFormatString"] = valueFormat

					continue

		oList["label"] = tagPart
		oList["newValue"] = ''
		oList["tagType"] = result['tagType']
		oList["engUnit"] = result['engUnit']
		oList["formatString"] = result['formatString']

		try:
			oList["valueSource"] = result['valueSource']
		except:
			oList["valueSource"] = ''
#		try:
#			oList["oldValue"] = result['value']
#		except:
#			oList["oldValue"] = 0

		tagList.append(oList)

		newStageTags = []
		for eachStage in writeTags:
			newList = {}

			newList["label"] = eachStage['label']
			newList["tagType"] = eachStage['tagType']
			newList["valueSource"] = eachStage['valueSource']

			newStageTags.append(newList)
		writeTags = newStageTags

	sortedTags = sorted(tagList,key=lambda k: k.get('value'))
	self.view.custom.tagList = sortedTags
	self.view.custom.writeTags = writeTags

	self.view.custom.UDTTags = results
	system.perspective.sendMessage('updateTagFilter')

tagList = self.view.custom.filteredTagList
writeTags = self.view.custom.writeTags
for eachTag in tagList:
	oList = {}

	if eachTag["newEngUnit"] != '' or eachTag["newFormatString"] != '':
		theIndex = 0
		for eachStage in writeTags:
			if eachStage['label'] == eachTag['label']:
				writeTags.pop(theIndex)
				theIndex += 1


		oList["label"] = eachTag['label']
		oList["tagType"] = eachTag['tagType']
		oList["engUnit"] = eachTag['engUnit']
		oList["formatString"] = eachTag['formatString']
		oList["newEngUnit"] = eachTag['newEngUnit']
		oList["newFormatString"] = eachTag['newFormatString']

		try:
			oList["valueSource"] = eachTag['valueSource']
		except:
			oList["valueSource"] = ''

		writeTags.append(oList)


sortedTags = sorted(writeTags,key=lambda k: k.get('value'))
self.view.custom.writeTags = sortedTags

try:
	provider = self.view.custom.provider.strip('[]')
except:
	return
query = {
  "options": {
    "includeUdtMembers": False,
    "includeUdtDefinitions": True
  },
  "condition": {
    "tagType": "UdtType",
    "attributes": {
      "values": [],
      "requireAll": True
    }
  },
  "returnProperties": [
    "tagType",
    "quality"
  ]
}
results = system.tag.query(provider, query)

UDTList = []
for result in results:

	dList = {}
	fullPath = str(result['fullPath']).replace("["+provider+"]_types_/","")

	dList["label"] = fullPath
	dList["data"] = fullPath
	dList["expanded"] = False
	dList["items"] = []

	UDTList.append(dList)

self.view.custom.allUDTTypes = UDTList
system.perspective.sendMessage('updateUDTFilter')

	try:
		provider = self.view.custom.provider.strip('[]')
		selectedUDTType = self.view.custom.selectedUDTType
	except:
		return

#	limit = 100

	query = {
	  "options": {
	    "includeUdtMembers": False,
	    "includeUdtDefinitions": False
	  },
	  "condition": {
	    "hierarchy": {
	      "typeId": selectedUDTType,
	      "relationship": "SubType"
	    },
	    "tagType": "UdtInstance",
	    "attributes": {
	      "values": [],
	      "requireAll": True
	    }
	  },
	  "returnProperties": [
		"tagType",
	    "quality"
	  ]
	}

	# Limited to 100 rows. Use continuationPoint functionality to continue from last result, 
	# or remove limit for full results.
	results = system.tag.query(provider, query)

	instanceList = []
	for result in results:
		oList = {}

		oList["label"] = result['fullPath']
		oList["selected"] = True

		instanceList.append(oList)

	sortedTags = sorted(instanceList,key=lambda k: k.get('label'))
	self.view.custom.allUDTInstances = sortedTags
	try:
		self.view.custom.firstInstance = sortedTags[0]['label']
		system.perspective.sendMessage('updateInstanceFilter')
		system.perspective.sendMessage('getUDTTags')
	except:
		return
